window.DIGEST.foryou.push(...[{"id": "2112677428531446006", "url": "https://x.com/jianchen1799/status/2112677428531446006", "text": "We just shipped Splash 1.4.0!\nQwen3.8-Flash-Next on an M5 Pro (64GB): up to 120 tok/s decode and 1.3K tok/s prefill at 32K.\nOver 30% faster prefill and decode than Strata. Up to 1M context, with bigger models fitting in less memory.\nhttps://github.com/incoai/splash", "name": "Jian Chen", "handle": "jianchen1799", "avatar": "https://pbs.twimg.com/profile_images/2008399095254151169/Zj7K_e5D_200x200.jpg", "likes": 207, "rts": 13, "replies": 14, "views": 17802, "ts": 1792536525, "media": [], "quote": {"id": "2101100749623341513", "url": "https://x.com/inco_ai/status/2101100749623341513", "text": "Qwen3.8-27B at 144 tok/s on an M5 Max MacBook Pro ⚡\n\nMeet Inco Splash: our open-source inference engine, built around the model and around Apple silicon.\n\nUp to 3× the decode speed of Ollama, 2× oMLX, and almost 4× when an agent fans out into sub-agents.", "name": "Inco AI", "handle": "inco_ai", "avatar": "https://pbs.twimg.com/profile_images/2110902509279879168/nBCMkD9B_200x200.jpg", "likes": 2517, "rts": 281, "replies": 192, "views": 975061, "ts": 1789776429, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2101100710301761536/vid/avc1/1280x720/tx_J8IfEK-9b8WFf.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2101100710301761536/vid/avc1/1920x1080/h4j9WYZuA3mTCGzT.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2101100710301761536/img/7PjPf-5nNhb-n2E7.jpg", "dur": 26}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.97, "thread": [], "tier": "must"}, {"id": "2112601748888322109", "url": "https://x.com/NotionHQ/status/2112601748888322109", "text": "Meet Auto, our upgraded model router 🔀\n\nFrontier quality at 90% lower cost. It matches each task to the right model, balancing quality, speed, and cost. And if it gets stuck, it changes course.", "name": "Notion", "handle": "NotionHQ", "avatar": "https://pbs.twimg.com/profile_images/1903224093476077568/OCclsw4c_200x200.jpg", "likes": 236, "rts": 12, "replies": 33, "views": 16952, "ts": 1792518481, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112601636686479360/vid/avc1/1280x720/nk9pnzOiTj5ATLLQ.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112601636686479360/vid/avc1/1920x1080/CTR6LUKStev9KkWu.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112601636686479360/img/8ktztjeVxq8eMq7q.jpg", "dur": 13}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.96, "thread": [], "tier": "must"}, {"id": "2112527557782630622", "url": "https://x.com/QwenDevs/status/2112527557782630622", "text": "Excellent work done by one of our ambassadors @KyleHessling1", "name": "Qwen Developers", "handle": "QwenDevs", "avatar": "https://pbs.twimg.com/profile_images/2079037454556987392/zGNYEiMo_200x200.jpg", "likes": 349, "rts": 8, "replies": 22, "views": 14572, "ts": 1792500793, "media": [], "quote": {"id": "2105029750419005856", "url": "https://x.com/KyleHessling1/status/2105029750419005856", "text": "Just got 150 tok/s decode with Qwen3.8 Flash-Next on a single 5090. All thanks to Niko1221's Strata engine and the ISTA Lab IQ3_S quant!\n\n1× 5090 + 128 GB DDR5 (non-ideal 4-stick dual-channel), single stream:\n\n150 tok/s decode for programming\n130 tok/s median on mixed prompts (~100 on long prose)\n4,150 tok/s prefill at 43K\nfull 262K context, 114 tok/s at 196K depth\n\n5.4× the speed of my best hybrid llama.cpp run.\n\nPer ISTA-DASLab's evals, their IQ3_S quant is at parity with BF16 on AIME25/GPQA/LCB, and it's holding up surprisingly well in my own tests!\n\nEngine: https://github.com/Niko1221/Strata\nQuant: https://huggingface.co/ISTA-DASLab/Qwen3.8-Flash-Next-GSQ-RCO-GGUF", "name": "Kyle Hessling", "handle": "KyleHessling1", "avatar": "https://pbs.twimg.com/profile_images/1831425378952286208/L-z1PfgV_200x200.jpg", "likes": 412, "rts": 36, "replies": 32, "views": 33382, "ts": 1790713176, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.95, "thread": [], "tier": "must"}, {"id": "2112571360996389078", "url": "https://x.com/viipin8/status/2112571360996389078", "text": "Not gonna lie, having a robot that tidies my home, finds my missing stuff, and fetches things for me sounds pretty appealing. 😂\n\nThat’s what caught my attention about Voxel. He’s a droid butler built around actual household help, with a little obsession for keeping everything perfect.\n\n@roboticscorp  is opening limited reservations for the first production run. I’m curious to see this one move from concept to real homes.", "name": "Vipin Gautam (Viipin I Gautam)", "handle": "viipin8", "avatar": "https://pbs.twimg.com/profile_images/2102723203718434817/Og3q0PY7_200x200.jpg", "likes": 175, "rts": 58, "replies": 6, "views": 44198, "ts": 1792511236, "media": [], "quote": {"id": "2112565146354860151", "url": "https://x.com/make_robot_go/status/2112565146354860151", "text": "Introducing Voxel, a droid butler made by Tuesday Labs.", "name": "Ros Shinkle", "handle": "make_robot_go", "avatar": "https://pbs.twimg.com/profile_images/1761551110303825920/JvPQiGQd_200x200.jpg", "likes": 2181, "rts": 228, "replies": 203, "views": 1849470, "ts": 1792509755, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112564839251931136/vid/avc1/960x720/cMYjra9bu_jYUTYR.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112564839251931136/vid/avc1/2880x2160/glhkyiQ6K97Rmq93.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112564839251931136/img/GKLfsqVaQmO0B-kn.jpg", "dur": 89}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.95, "thread": [], "tier": "must"}, {"id": "2112628202594349139", "url": "https://x.com/markchen90/status/2112628202594349139", "text": "Excited to welcome Orchestra Bio and @ashokaraj_ to OpenAI as we broaden our work in AI-assisted drug discovery!", "name": "Mark Chen", "handle": "markchen90", "avatar": "https://pbs.twimg.com/profile_images/1273327644436656129/uYf1oNS5_200x200.jpg", "likes": 263, "rts": 8, "replies": 9, "views": 11956, "ts": 1792524788, "media": [], "quote": {"id": "2112607347688583586", "url": "https://x.com/OpenAI/status/2112607347688583586", "text": "We’ve acquired Orchestra Bio, a platform that helps biopharma teams coordinate the complex process of drug development.\n\nTogether, we’ll build on Rosalind, our AI models and tools for life sciences research, to streamline those operations and help new treatments reach patients sooner.\n\nWelcome @ashokaraj_ and team!\n\nhttps://openai.com/index/openai-to-acquire-orchestra-bio/", "name": "OpenAI", "handle": "OpenAI", "avatar": "https://pbs.twimg.com/profile_images/1885410181409820672/ztsaR0JW_200x200.jpg", "likes": 5905, "rts": 522, "replies": 371, "views": 545409, "ts": 1792519816, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.95, "thread": [], "tier": "must"}, {"id": "2112507166900813848", "url": "https://x.com/nft_parker_/status/2112507166900813848", "text": "I am really happy to be in a position where I can provide so many opportunities to creators.\n\nAnd I love the campaigns we're running.\n\nThey create insane amounts of mindshare for our clients, putting them at the top ranks in mindshare and smart engagement rankings.\n\nBut there's one thing that honestly bothers me.\n\nSeeing a lot of creators only farming InfoFi and becoming a complete billboard.\n\nNo personality.\n\nYou could replace the person running the account with an AI agent and probably wouldn't even notice the difference.\n\nAnd it actually frustrates me.\n\nBecause I’m seeing so much potential there.\n\nSo many creators deciding to not build a brand and aiming for something bigger with their accounts, but being ok with posting these AI content pieces several times a day.\n\nDon't get me wrong. There's absolutely nothing wrong with monetizing your account. I literally help creators do that every day.\n\nBut there's a difference between monetizing your audience and turning your entire identity into advertising space.\n\nI just hope more creators realize how much potential they're leaving on the table and start building something that actually lasts.", "name": "David Parker", "handle": "nft_parker_", "avatar": "https://pbs.twimg.com/profile_images/1886415000438255616/fiQaMdCs_200x200.jpg", "likes": 196, "rts": 10, "replies": 108, "views": 5422, "ts": 1792495931, "media": [], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.95, "thread": [], "tier": "must"}, {"id": "2112639437482176693", "url": "https://x.com/arena/status/2112639437482176693", "text": "Exciting news: Muse Wonder Full (Max) has moved up @AIatMeta as the #4 lab in the Agent Arena!\n\nThe latest model ranks #7 in Agent Arena with +11.3% net improvement across +6.5K real-world agentic sessions.\n\nThis is a clear step forward for the Muse family:\n\n+7.5 percentage points over Muse Wonder (Max), ranked #14 at +3.8%\n+7.8 percentage points over Muse Spark 1.3 (Max), ranked #17 at +3.5%\n\nThis performance shows up across categories too: #5 in Chat, #6 in Code, and #7 in Work.\n\nAt the signal level, Muse Wonder Full (Max) ranks:\n\n- #6 in Praise vs. Complaint (+21.9%)\n- #6 in Confirmed Success (+13.4%)\n- #7 in Steerability (+11.2%)\n- #16 in Bash Reliability (+7.7%)\n- No issues in Tool Hallucination\n\nCongrats to the @AIatMeta team and @alexandr_wang!", "name": "Arena.ai", "handle": "arena", "avatar": "https://pbs.twimg.com/profile_images/2017015061454438400/iNKfXZ_I_200x200.jpg", "likes": 199, "rts": 16, "replies": 19, "views": 16685, "ts": 1792527467, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVGaK7ebAAAtII6.jpg?name=orig"}], "quote": {"id": "2112215825944117361", "url": "https://x.com/arena/status/2112215825944117361", "text": "Exciting news: Muse Wonder Full (Max) by @AIatMeta has just debuted in the Code Arena: WebDev at #6 overall with 1726 pts, putting Meta in the top 3 labs!\n\nThis is +75 pts and 11 places above Muse Wonder (Max) at #17 (1651 pts), and +67 pts and 8 places above Muse Spark 1.3 (Max) at #14 (1659 pts).\n\nMuse Wonder Full (#6) also landed +16 pts above Claude Sonnet 5.5 (#17), and +48 pts above Gemini 4 Argon (#10). With this score, Muse took the #3 lab spot (previously held by Google).\n\nAcross categories, Muse Wonder Full (Max) landed:\n- #4 in Data & Analytics and in Consumer Product\n- #5 in Brand & Marketing \n- #6 in Content Creation Tools\n- #7 in Gaming and in Simulations\n- #8 in Reference-Based Design\n\nCongrats to the @AIatMeta team and @alexandr_wang on this release!", "name": "Arena.ai", "handle": "arena", "avatar": "https://pbs.twimg.com/profile_images/2017015061454438400/iNKfXZ_I_200x200.jpg", "likes": 298, "rts": 28, "replies": 28, "views": 99134, "ts": 1792426470, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVAY5ESaQAAMRs1.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.94, "thread": [], "tier": "must"}, {"id": "2112640910420812063", "url": "https://x.com/vikktorrrre/status/2112640910420812063", "text": "Demis Hassabis: AI could become self-aware, even if that isn’t the goal.\n\n“I don’t think any of today’s systems feel self-aware or conscious in any way.”\n\n“Not explicitly, but it may happen implicitly.”\n\n“These systems might acquire some feeling of self-awareness.”\n\n“They don’t have curiosity. They’re probably lacking imagination and intuition.”\n\n“But in the next five to 10 years, I think we’ll have systems capable of not only solving an important problem in science, but coming up with it in the first place.”", "name": "Veee", "handle": "vikktorrrre", "avatar": "https://pbs.twimg.com/profile_images/2012714142877044736/_6qWAbnU_200x200.jpg", "likes": 174, "rts": 16, "replies": 30, "views": 16869, "ts": 1792527818, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112640492026388481/vid/avc1/1280x720/H1G1PXu1HQBwBp31.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112640492026388481/vid/avc1/1920x1080/RCbehQxs4TLkt9Nc.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112640492026388481/img/hGzK8kE53FVcsiZ5.jpg", "dur": 120}], "quote": null, "reply_to": null, "cat": "Research & Safety", "score": 5.94, "thread": [], "tier": "must"}, {"id": "2112743579206705202", "url": "https://x.com/CodeByAurelia/status/2112743579206705202", "text": "The Tesla Roadster is the kind of product that calls for strong visuals and a clear story. \n\nBut getting from an idea to a marketing video can take time. \n\nCapCut Web × Codex offers a more natural workflow: describe the video you want, let Codex interpret your direction, and have CapCut Web help create the draft.\n\nYour creative brief becomes the starting point for AI editing, making the journey from concept to content feel more connected.\n\n#capcutweb #capcutcodex #capcutmarketing #capcutchatgptplugin", "name": "Aurelia Vance", "handle": "CodeByAurelia", "avatar": "https://pbs.twimg.com/profile_images/2041821924087754753/TiuxjXBd_200x200.jpg", "likes": 146, "rts": 3, "replies": 23, "views": 62531, "ts": 1792552296, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112743337698680832/vid/avc1/1280x720/Fh8Iqtv02TBj-jRS.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112743337698680832/vid/avc1/1920x1080/iDOUtYp8OFv-E4xJ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112743337698680832/img/Rldm5ctHkvjrg2nN.jpg", "dur": 38}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.93, "thread": [], "tier": "must"}, {"id": "2112577528363643160", "url": "https://x.com/painn_x/status/2112577528363643160", "text": "WTFFF, this is actually insane 💀\n\nOpus 5.5, gpt-6 astra and 34 more models are FREE on radoxai right now\n\nand i'm running it on deepseek's own agent harness (dsh) for $0 \n\nno subscription.\n\nhere is how you set it up:\n1. go to http://radoxai.com/?ref=CC4DZBBC— sign up \n2. run npx @deepseek-ai/dsh web\n3. open http://127.0.0.1:3080\n4. settings → add custom provider → base url https://radoxai.com/v1 → pick opus 5.5\n\ndone. full agent harness on the free lineup for $0\n\nmilk it before they take it off 👀", "name": "painn", "handle": "painn_x", "avatar": "https://pbs.twimg.com/profile_images/2092990665332248576/k2gtKRhN_200x200.jpg", "likes": 240, "rts": 15, "replies": 25, "views": 15627, "ts": 1792512707, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112576934458642432/vid/avc1/1280x720/0rfQnyTdE9L2Cwm2.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112576934458642432/vid/avc1/3024x1700/eMN3vIIMYpNrJozh.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112576934458642432/img/NgmzivlCjjMpJnaY.jpg", "dur": 53}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.92, "thread": [], "tier": "must"}, {"id": "2112615167716659432", "url": "https://x.com/sonyatweetybird/status/2112615167716659432", "text": "Biological intelligence to bootstrap robotic intelligence?\n\nIf robotics is about to enter its golden age, @MeckaAI is one of the companies feeding it, by sensorizing humans to train robots.\n\nThe biggest challenge robotics faces is the data flywheel cold start problem. LLMs got a free cold start from the internet: trillions of tokens, already written. Robotics gets nothing. Someone has to go create the training data to jumpstart the system.\n\n@joshavata is the co-founder and CEO of Mecka, the data and deployment company for physical AI. Josh read every robotics paper he could find in late 2024, visited the labs, and made a bet: humans and humanoids look the same, so humans could act as the training fleet. Egocentric data, first-person video of people doing real work, could become vital fuel.\n\nTwo years ago, the biggest egocentric dataset was Ego4D at 4,000 hours. The field is now in the millions of hours, thanks in part to Mecka. We’re probably still orders of magnitude of training data away from robotics nirvana. But every rung on the physical intelligence ladder unlocks real commercial tasks. And eventually, Josh imagines a world with an order of magnitude more robots than people, of a plurality of shapes and sizes and use cases, as the Hitchhiker’s Guide to the Galaxy foretold :)\n\nA few things we cover in this conversation.\n\n- Why robotics has no cold start: pixels, actions and logic, and why pre-training data is a real market in robotics in a way it never was for LLMs\n\n- What “teaching robots about carbon life” means: in sci-fi the final frontier is organic. The human brain runs on 20 watts and self-heals\n\n- The egocentric bet: teleop couldn’t scale, humans and humanoids share a form, so Waymo-fy the humans. The first pilot was aunties and uncles recording themselves cooking on a mobile app\n\n- Force data: video can’t tell a robot how hard to squeeze an egg. Wrist cameras are a hack. Mecka built the gloves instead\n\n- Inside the data factory: a consumer app that streams your tasks, a B2B engine recruiting across “the taxonomy of all physical human work,” 100-gigabit upload lines, hundreds of petabytes\n\n- Millions of hours vs. Tesla’s decade on two degrees of freedom, and why it’s a slow creep up, not a GPT-3 moment\n\n- The home has the most data and is the hardest place to deploy. Laundry folding and assembly-line pick-and-place get solved in the next year or two\n\n- Useful robots already exist: hotel delivery and cleaning bots in China and Southeast Asia, industrial cleaning in the US. Humanoids are the terminal state, not the first step\n\n- Deployment diffusion: a modern systems integrator whose installed robot does something next week it couldn’t do last week. If Mecka ever helps deploy a robot that mines an asteroid, they’ve done their job\n\n- The data pot of soup: a million hours of human data, tens of thousands of UMI, a few hours of in-domain teleop. Tactile and simulation haven’t entered the mix yet\n\n- Move 37 for robotics: AlphaGo went behavior cloning, then self-play, then magic. The catch is the rules of the game are the entire physical world, and we don’t have the simulator yet\n\n- Will the AGI labs steamroll robotics? “It takes a lot of courage to scale up data with imperfect information.”\n\n- The Kawasaki Corleo, the robot panther-dog-horse on Mecka’s conference room wall, and why the future of robotics looks like Hitchhiker’s Guide to the Galaxy\n\nTimestamps:\n\n0:00 – Introduction\n1:46 – What Mecka is: pixels, actions and logic\n2:45 – Is robot data economically feasible without the internet?\n4:15 – Teaching robots about carbon life\n5:27 – Cloud kitchens, stablecoins and the path to robotics\n7:03 – Entering robotics with a fresh lens\n8:45 – What egocentric data is and why Mecka bet on it\n10:09 – The first pilot: aunties and uncles with a mobile app\n10:42 – Force data and tactile gloves\n11:55 – Inside the operations of a data factory\n14:41 – Heat-mapping the taxonomy of human work\n15:42 – Quality gates, fraud and the McDonald’s POV videos\n17:44 – Earning a margin as a data intermediary\n19:33 – Millions of hours vs. Tesla’s decade\n20:55 – Why it isn’t binary: unlocking commercial tasks along the way\n22:02 – Home data is plentiful; home robots are the hardest\n23:24 – Useful robots can be deployed today\n24:35 – When robotics gets an FSD-style flywheel\n26:42 – Deployment diffusion and the modern systems integrator\n28:21 – Favorite vertical robot categories; mining an asteroid\n30:08 – The hardware slate: Waymo-fying people\n30:55 – EgoVerse\n32:04 – The data pot of soup: the converged training mix\n33:54 – Move 37 for robotics: AlphaGo and Federer\n36:02 – World models and the training mix\n36:58 – Will scaling the current mix get us to the promised land?\n39:05 – Will the AGI labs steamroll robotics?\n40:50 – Sci-fi roots and the Kawasaki Corleo\n42:44 – How many robots in a decade?", "name": "Sonya Huang 🐥", "handle": "sonyatweetybird", "avatar": "https://pbs.twimg.com/profile_images/2080547965408886784/IZjjuKBJ_200x200.jpg", "likes": 141, "rts": 33, "replies": 27, "views": 19880, "ts": 1792521681, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112614606392983552/vid/avc1/1280x720/bxnKneoxFMlmyL-w.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112614606392983552/vid/avc1/1920x1080/q-C7G0BeJX3OEhTY.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112614606392983552/img/vc46Zkn9-34xLxoW.jpg", "dur": 2712}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.92, "thread": [], "tier": "must"}, {"id": "2112658104102064278", "url": "https://x.com/chrismaddern/status/2112658104102064278", "text": "It's been a little over a year now since we (@opensea) acquired @rally_xyz (also we 🙈) & it's been quite a year!\n\nTogether, we set out to build a whole new OpenSea from the ground up. Mobile, social, omni-chain, every asset. \n\nA single home for all culture & assets onchain. \nToday is a huge step forward for this vision 🎉\n\n📱 OpenSea Mobile is now live for everyone & brings all of your wallets, chains & assets into one app\n\n👥 One global social feed (on Web + Mobile) lets you collect, and trade together - follow users across every major social trading app in one place\n\n📢 Signals share the “why” of what you do onchain - for the first time available for both NFTs and Tokens\n\n⚡️ The fastest notifications keep you ahead of everyone else\n\n⛵️ And we did a nice little brand refresh to reflect our evolution\n\nTo recognize & reward the work you do to share OpenSea with the world, we’re launching referral rewards today -- earn 25% of the fees from users you refer💰\n\nand, as a thank you to our beta testers, all referrals during the beta period will be active going-forward for referral rewards 🎉 🎉\n\nWe believe that OpenSea Mobile is a new type of onchain product that combines power & simplicity in a way not seen before\n\nWe’re also listening and learning — we believe that the world (us humans and agents) are inevitably coming onchain.\n\nWe believe that future will be mobile-first, it will be social, and mostly we believe it’ll be the next era of the cultural assets revolution that NFTs began.\n\nWe’re here for it. And we’re just getting started.\n\nTry it out, and let us know what you think 🙏👇\nhttp://opensea.io/r/chrismaddern", "name": "Chris Maddern", "handle": "chrismaddern", "avatar": "https://pbs.twimg.com/profile_images/1952689747849080832/bl89Lef3_200x200.jpg", "likes": 166, "rts": 10, "replies": 30, "views": 7115, "ts": 1792531917, "media": [], "quote": {"id": "2112654029595529229", "url": "https://x.com/opensea/status/2112654029595529229", "text": "OpenSea Mobile is now open to everyone.  \n\nEverything you own. Everything you trade. Everyone you trade with.  \n\nMemes, art, trading cards, perps. 25+ chains, all your wallets, one app.  \n\nTrade everything, together.", "name": "OpenSea", "handle": "opensea", "avatar": "https://pbs.twimg.com/profile_images/2112614202011537408/I-WGhmg2_200x200.jpg", "likes": 1767, "rts": 303, "replies": 545, "views": 199548, "ts": 1792530946, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112588539883843586/vid/avc1/1280x720/3s97S5mJ1pQINx-m.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112588539883843586/vid/avc1/1920x1080/nYtqw-Rkus3ooD7v.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112588539883843586/img/79r4M1L0NEPlqY8F.jpg", "dur": 84}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.92, "thread": [], "tier": "must"}, {"id": "2112501028117741648", "url": "https://x.com/cb_doge/status/2112501028117741648", "text": "BREAKING: Elon Musk in his new interview on rival SI companies testing each other’s models to make super intelligence safer:\n\n“Guys, what if we just have a call once a week, just like you’re saying, and that maybe a week before we release a model, we give access to our competitors to say, hey guys, why don’t you try out the new model, see if you see any problems with it.\n\nI think competitors would keep each other honest in that situation. If they say, oh, I was able to make a nuclear bomb with your AI, it’s like, well, we better fix that before we release it, you know, type of thing.”", "name": "DogeDesigner", "handle": "cb_doge", "avatar": "https://pbs.twimg.com/profile_images/1498070100393754625/C2V-fbll_200x200.jpg", "likes": 234, "rts": 36, "replies": 43, "views": 28356, "ts": 1792494468, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112500958823682048/vid/avc1/720x720/4t_qDLvkuO198i-J.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112500958823682048/vid/avc1/1080x1080/JlLrGQdH-vqS0Q0A.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112500958823682048/img/y4-PjKhCQk0lVPQ2.jpg", "dur": 78}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.92, "thread": [], "tier": "must"}, {"id": "2112546509250273370", "url": "https://x.com/thetripathi58/status/2112546509250273370", "text": "a lot of AI research eventually leads you back to the same handful of articles.\n\nQualitate is building its own source material: thousands of interviews with vetted experts each month, organized into research you can query. \n\n“Why did customers cut their spending?” often hasn’t been written down anywhere. Someone has to go ask. \n\nThe library is there before you arrive. You can find out what’s already known, then launch a custom study around the questions that are still open.", "name": "Chidanand Tripathi", "handle": "thetripathi58", "avatar": "https://pbs.twimg.com/profile_images/1887399788649586690/gJLTJ29F_200x200.jpg", "likes": 180, "rts": 39, "replies": 35, "views": 105916, "ts": 1792505311, "media": [], "quote": {"id": "2112544300751896702", "url": "https://x.com/S_Kadakia/status/2112544300751896702", "text": "We just raised $25M from Insight Partners to replace Gartner, McKinsey, and GLG.\n\nRIP the Quadrant, the 80-page consulting deck, and the $2000 expert network call.\n\nOur revenue run-rate is up 10x+ this year.\n\n100+ investment firms and enterprises use Qualitate to inform decisions with firsthand evidence.\n\nHere's how:\n\nhttps://www.qualitate.io/book-a-demo", "name": "Sagar Kadakia", "handle": "S_Kadakia", "avatar": "https://pbs.twimg.com/profile_images/2039423331938762752/vCFGOdIb_200x200.jpg", "likes": 733, "rts": 130, "replies": 137, "views": 296881, "ts": 1792504785, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112544190240358400/vid/avc1/1280x720/QaACj_QBWPQJcK__.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112544190240358400/vid/avc1/1920x1080/KgN176ObrVpGqv7K.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112544190240358400/img/Pw2JDRrY--NClwef.jpg", "dur": 133}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.92, "thread": [], "tier": "must"}, {"id": "2112669039009104059", "url": "https://x.com/figma/status/2112669039009104059", "text": "Specs are here and they can do a lot\n\n→ Create data reports, PRDs, generate hand-off context\n→ Bring in outside context with an agent\n→ Turn rough ideas into a detailed spec\n→ Send it to a coding agent using Figma’s MCP server\n→ Build a Code Layer on top and refine", "name": "Figma", "handle": "figma", "avatar": "https://pbs.twimg.com/profile_images/2068849889753333760/YE3KJq___200x200.jpg", "likes": 161, "rts": 11, "replies": 24, "views": 13883, "ts": 1792534525, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112667483945496576/vid/avc1/1280x720/41GJoZLxCDq5wa7m.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112667483945496576/vid/avc1/1920x1080/rk5rY6mmLIfTM0VD.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112667483945496576/img/7cG8jFGOKBdhtL5G.jpg", "dur": 778}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.91, "thread": [], "tier": "must"}, {"id": "2112664888409473269", "url": "https://x.com/dravenip/status/2112664888409473269", "text": "WHY ARE WE PAYING SO MUCH FOR BROWSER AGENTS?\n\nnace ai just launched drex for browser use, powered by drex max.\n\nthe numbers are kinda crazy:\n\n→ $2.80 per 1,000 miniwob++ tasks vs $31 with claude code\n\n→ frontier-level browser performance at a fraction of the cost\n\n→ $25 in free credits to get started\n\nif you're building agents that interact with the web, this is worth checking out.\n\nhttp://console.nace.ai", "name": "draven", "handle": "dravenip", "avatar": "https://pbs.twimg.com/profile_images/2094585676800860160/6Xm8L9f6_200x200.jpg", "likes": 188, "rts": 8, "replies": 13, "views": 12124, "ts": 1792533535, "media": [], "quote": {"id": "2112642726877405531", "url": "https://x.com/NaceAI/status/2112642726877405531", "text": "Drex for Browser Use is here!\nClaude Sonnet level accuracy at the fraction of the cost\n\n1,000 browser tasks:\nDrex Harness: $1.30\nClaude Code: $24\nCodex: $28\n\nStart here: https://console.nace.ai", "name": "Nace AI", "handle": "NaceAI", "avatar": "https://pbs.twimg.com/profile_images/1904211985488871426/z5Z5rKcl_200x200.jpg", "likes": 35, "rts": 3, "replies": 2, "views": 10948, "ts": 1792528251, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112641445072863232/vid/avc1/1280x720/23NgPCKVh98EcT2v.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112641445072863232/vid/avc1/1920x1080/z1L4KIGq6dUIF_hr.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112641445072863232/img/-LV0zfzJWhLJdvBA.jpg", "dur": 27}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.9, "thread": [], "tier": "must"}, {"id": "2112596976856690863", "url": "https://x.com/AItechscarlett/status/2112596976856690863", "text": "Same beat, same vibe, but a tiny knight cat takes center stage! 🐱✨\n\nImagine a little feline starring in a “Wannabe” music video 🎬⚔️ The idea came to life with @flovaai, blending a reference video with music to create something fun and completely unexpected.\n\nTiny cat, big main-character energy! 🐾🔥\n\n🚀 Made with @flovaai", "name": "Scarlett", "handle": "AItechscarlett", "avatar": "https://pbs.twimg.com/profile_images/2106591501480501248/2cdAD_95_200x200.jpg", "likes": 101, "rts": 57, "replies": 9, "views": 515, "ts": 1792517344, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112596929180049408/vid/avc1/362x360/YxDpQbp1hOwIsr9e.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112596929180049408/vid/avc1/726x720/nwmokAq0jG0vq9oY.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112596929180049408/img/oysIlNI87-j4ipUU.jpg", "dur": 66}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.89, "thread": [], "tier": "must"}, {"id": "2112610230043312618", "url": "https://x.com/testingcatalog/status/2112610230043312618", "text": "OpenAI ❤️ Orchestra Bio\n\n> OpenAI has acquired Orchestra Bio⁠ to work on Rosalind models and tools for life sciences research.\n\n> \"Orchestra Bio is a platform that helps biopharma teams coordinate the complex process of drug development.\"\n\nAI advancements in life sciences are probably one of the most desired areas for many. So far, it seems like a top priority for Anthropic, OpenAI, and Google.", "name": "🚨 AI News | TestingCatalog", "handle": "testingcatalog", "avatar": "https://pbs.twimg.com/profile_images/1899962463115751424/i-6MBWau_200x200.jpg", "likes": 217, "rts": 14, "replies": 12, "views": 10642, "ts": 1792520503, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVF_hgjXwAAb-j7.jpg?name=orig"}], "quote": {"id": "2112607347688583586", "url": "https://x.com/OpenAI/status/2112607347688583586", "text": "We’ve acquired Orchestra Bio, a platform that helps biopharma teams coordinate the complex process of drug development.\n\nTogether, we’ll build on Rosalind, our AI models and tools for life sciences research, to streamline those operations and help new treatments reach patients sooner.\n\nWelcome @ashokaraj_ and team!\n\nhttps://openai.com/index/openai-to-acquire-orchestra-bio/", "name": "OpenAI", "handle": "OpenAI", "avatar": "https://pbs.twimg.com/profile_images/1885410181409820672/ztsaR0JW_200x200.jpg", "likes": 5905, "rts": 522, "replies": 371, "views": 545241, "ts": 1792519816, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.89, "thread": [], "tier": "must"}, {"id": "2112567086904160455", "url": "https://x.com/daleverett/status/2112567086904160455", "text": "Today we’re launching WonderSearch (@ycombinator F26).\n\nIn 1977 we put everything humanity knew on one golden record and launched it into space.\n\nIn 2026 your AI agent still can’t find last week’s contract.\n\nWonderSearch is search for AI agents. It finds anything in your data, instantly, with zero embeddings: no vector database, just the exact passage and its source.\n\nThank you to all of our early users!\n\n@wondersearchai", "name": "dale", "handle": "daleverett", "avatar": "https://pbs.twimg.com/profile_images/2049549782755205121/y6qaHyA-_200x200.jpg", "likes": 142, "rts": 23, "replies": 57, "views": 8697, "ts": 1792510217, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112564740748955648/vid/avc1/1280x720/fdwLhV7ZVkl1YMvp.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112564740748955648/vid/avc1/1920x1080/1ZCDi5baWbQn1A2L.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112564740748955648/img/ZogCf485q7x_Ogyd.jpg", "dur": 37}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.89, "thread": [], "tier": "must"}, {"id": "2112645094540988549", "url": "https://x.com/AkoolInc/status/2112645094540988549", "text": "Your story deserves the big screen.\n\nBring your vision to life with AKOOL and submit your original film to the AKOOL AI Film Challenge. From the first frame to the final twist, show us what you can imagine.\n\nReady to roll? Visit Akool page for details.", "name": "Akool Inc", "handle": "AkoolInc", "avatar": "https://pbs.twimg.com/profile_images/1857138415109910528/iJ47_VAr_200x200.jpg", "likes": 202, "rts": 15, "replies": 3, "views": 11547, "ts": 1792528816, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112645041516691457/vid/avc1/1280x720/-7oQ88bIXsfBcOD8.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112645041516691457/vid/avc1/1920x1080/VDvDW8jr7Ony0FMo.mp4?tag=16", "thumb": "https://pbs.twimg.com/media/HVGfhGnW4AALCa2.jpg", "dur": 38}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.89, "thread": [], "tier": "must"}, {"id": "2112565310519746660", "url": "https://x.com/I_amShiti/status/2112565310519746660", "text": "Frontier-level performance on a single NVIDIA DGX card is a big deal. \n\nOrnith-1.5-122B could make powerful AI workflows more accessible while delivering the speed and efficiency developers need.", "name": "Kuria | AI", "handle": "I_amShiti", "avatar": "https://pbs.twimg.com/profile_images/2036423514660708352/PtFecw86_200x200.jpg", "likes": 83, "rts": 59, "replies": 24, "views": 8162, "ts": 1792509794, "media": [], "quote": {"id": "2112553477457268799", "url": "https://x.com/ornith_/status/2112553477457268799", "text": "Aloha!🌺 Meet Ornith-1.5-122B: No Tradeoff Between Strong and Fast  \n\nStronger. Faster. Leaner. Ornith-1.5-122B delivers frontier-level capabilities with exceptional inference efficiency. With superior instruction following, stronger task decomposition, and deeper understanding of real-world workflows, it achieves state-of-the-art performance among open-source models of comparable size, while running on a single NVIDIA DGX card!!\n\nOpen weights under the MIT license.\nCoding \n✅SWE-bench Verified: 0.845 \n✅TB2.1: 0.813 \n✅CyberGym: 0.800 \n✅NL2Repo: 0.512 \nAgentic \n✅HLE: 0.446 \n✅BrowseComp: 0.785 \n✅MCP-Atlas: 0.746 \n✅Toolathlon: 0.708  \n\n🤗Hugging Face: https://huggingface.co/ornith-ai/Ornith-1.5-122B \nWe can’t wait to see what you build with Ornith-1.5-122B.", "name": "Ornith", "handle": "ornith_", "avatar": "https://pbs.twimg.com/profile_images/2067467120544456704/qYuod4O1_200x200.jpg", "likes": 2374, "rts": 432, "replies": 177, "views": 1086684, "ts": 1792506973, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFMLvWbAAE3955.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.87, "thread": [], "tier": "must"}, {"id": "2112635366159352101", "url": "https://x.com/ollama/status/2112635366159352101", "text": "Clef from @Cloudflare is on Ollama. Run it locally or in the cloud.\n\n27B multimodal decision model, supports text and image input and is compatible with Jev and System One APIs.\n\n🔒Hosted in the US and with zero data retention.", "name": "ollama", "handle": "ollama", "avatar": "https://pbs.twimg.com/profile_images/2045273960666071040/rCjCIwiC_200x200.jpg", "likes": 174, "rts": 16, "replies": 12, "views": 14352, "ts": 1792526496, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.87, "thread": [], "tier": "must"}, {"id": "2112587892031987885", "url": "https://x.com/aresotik/status/2112587892031987885", "text": "NUEVO MODELO DE NEGOCIO: SHOPIFY + KREA 3\n\nTodo el mundo vende el mismo producto con las mismas fotos del proveedor.\n\nAsí nadie se fía y nadie compra.\n\nAhora subes una sola foto a Krea 3 y te saca decenas:\n\n→ En la mano\n→ En estudio\n→ En la calle\n→ Con cualquier fondo\n\nY el producto sale idéntico en todas.\nMira el vídeo.", "name": "ares. 🎧", "handle": "aresotik", "avatar": "https://pbs.twimg.com/profile_images/2040850171274440704/ZyELtIL__200x200.jpg", "likes": 195, "rts": 23, "replies": 10, "views": 27632, "ts": 1792515178, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112587862961238016/vid/avc1/1280x720/Zd8mffDcJq_lDjT1.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112587862961238016/vid/avc1/1920x1080/ZLQ5Ge4VPdoDxod0.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112587862961238016/img/Lsb_Z1k-pMudfaiy.jpg", "dur": 14}], "quote": {"id": "2112567020353102324", "url": "https://x.com/krea_ai/status/2112567020353102324", "text": "today, Krea 3 makes it to the top of image arenas.\n\n- \"Fast\" pushes the pareto curve of speed and quality.\n- \"Ultra\" ranks top-4, only surpassed by OpenAI models.\n\nthe only company valued under $1T in the top-10!\n\nmore below 👇", "name": "Krea", "handle": "krea_ai", "avatar": "https://pbs.twimg.com/profile_images/2052148578588753920/deUXA7cZ_200x200.jpg", "likes": 1097, "rts": 143, "replies": 103, "views": 911816, "ts": 1792510201, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112560706319261696/vid/avc1/1280x720/I09XfdJSlPHN1GRN.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112560706319261696/vid/avc1/1920x1080/dNLTktxkBQvdw6CQ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112560706319261696/img/adh7bZDj88TDFAP8.jpg", "dur": 35}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.87, "thread": [], "tier": "must"}, {"id": "2112423796527559136", "url": "https://x.com/Bhavani_00007/status/2112423796527559136", "text": "MiniMax M3.1 Flash is actually insane.\n\nI asked it to build this whale breach scene using Claude Code as the harness, and it cost just $0.25. That's roughly 8x cheaper than Astra and Sol.\n\nI didn't expect MiniMax to be this good at 3D. \n\nIn my testing, it even beats GPT 6.1 Sol, and the result looks better than the others while costing less than DeepSeek Flash’s version.\n\nWhat a comeback by MiniMax.", "name": "Bhavy☄️", "handle": "Bhavani_00007", "avatar": "https://pbs.twimg.com/profile_images/1980236068583559168/dEO9pxtO_200x200.jpg", "likes": 375, "rts": 8, "replies": 39, "views": 45226, "ts": 1792476054, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112423597914636288/vid/avc1/720x720/lXfGRPi0JaYyUrTo.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112423597914636288/vid/avc1/1600x1600/sj_EduETrMjwlg16.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112423597914636288/img/b66Rjcd03YAlusGq.jpg", "dur": 18}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.86, "thread": [], "tier": "must"}, {"id": "2112529276633247757", "url": "https://x.com/vangrid_io/status/2112529276633247757", "text": "The physical world is now orderable.\n\nPost a bounty for a real place. Someone nearby films it on their phone. Proof of capture lands onchain. You get the 3D model.\n\nhttps://data.vangrid.io", "name": "Vangrid", "handle": "vangrid_io", "avatar": "https://pbs.twimg.com/profile_images/2040693410604961792/gq4efyi__200x200.jpg", "likes": 130, "rts": 25, "replies": 61, "views": 16532, "ts": 1792501203, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2111374481092644864/vid/avc1/1280x720/GdGeFQh-Z7CTrBOh.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2111374481092644864/vid/avc1/1920x1080/-IhyTjGVWAjtTYVi.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2111374481092644864/img/-fvxgJasDmD_UpR8.jpg", "dur": 36}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.85, "thread": [], "tier": "must"}, {"id": "2112681768885297530", "url": "https://x.com/TimJayas/status/2112681768885297530", "text": "so finally the legendary opus 5.5 has been nerfed too\n\nwhy would anthropic do this to them when everything is going perfectly well? i believe they’re testing the harness, making new changes to prepare for the upcoming fable 5.5 and this always happens whenever a new big model is about to launch \n\nthis is the only possible reason behind it or else why would they intentionally nerf a model when they’re already winning?", "name": "Tim Jayas", "handle": "TimJayas", "avatar": "https://pbs.twimg.com/profile_images/2016190209768226821/MW5mAfL-_200x200.jpg", "likes": 128, "rts": 4, "replies": 31, "views": 8682, "ts": 1792537560, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.85, "thread": [], "tier": "must"}, {"id": "2112598586831876262", "url": "https://x.com/tec_marco10/status/2112598586831876262", "text": "I generated $7625 overnight using an automated Claude setup.\n\nI’ve documented the exact, step-by-step process behind this timezone arbitrage strategy.\n\nWhat you need👇\n• Claude\n• A Mobile\n• 24 hours to test it ( no cost )\n\nHow to access the guide👇\n1. Comment “ SetUp ”\n2. Like & RT\n3. Follow @tec_marco10 (so I can send it via DM)\n\nThe system runs continuously, scanning global news across Japanese, European, Australian, and Middle Eastern markets.\n\nIt identifies pricing inefficiencies situations where outcomes are already reflected overseas, but U.S. markets have yet to adjust.\n\nAfter 9 days of running this setup, the results have been consistent and eye opening.\n\nMost traders focus on EST. Markets don’t.\n\nWhile one region sleeps, another resolves events in real time.\n\nThat timing gap is the opportunity.\n\nFollow @tec_marco10 to receive the full breakdown.\n\n( First 1500 people will get it! Like, comment, and follow quickly )", "name": "Holland Tech Marco", "handle": "tec_marco10", "avatar": "https://pbs.twimg.com/profile_images/2080916766952460288/U3vNCM9I_200x200.jpg", "likes": 59, "rts": 40, "replies": 38, "views": 2241, "ts": 1792517727, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112598509719556096/vid/avc1/720x900/-3uk-_uKTuvOfzeF.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112598509719556096/vid/avc1/1080x1350/T72vRLH1IVYV1nHy.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112598509719556096/img/kenVMAIfzneJB79l.jpg", "dur": 23}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.83, "thread": [], "tier": "must"}, {"id": "2112543436591018106", "url": "https://x.com/amirshanehsaz/status/2112543436591018106", "text": "🦂 This was a very fun collaboration with the team @citrini! Thank you to @TwistBioscience and @adaptyvbio for the rapid turnaround on experimental validation and to Susana Vázquez Torres (@CNIOStopCancer), Tim Jenkins (@DTUtweet ), and Dan Bedinger (@carterra_bio) for their thoughtful review.\n\nRead more in our blog post: https://www.anthropic.com/research/claude-scorpion-toxin-binder-design", "name": "Amir Shanehsazzadeh", "handle": "amirshanehsaz", "avatar": "https://pbs.twimg.com/profile_images/1469848771303378946/HiHJVs70_200x200.jpg", "likes": 225, "rts": 20, "replies": 10, "views": 42029, "ts": 1792504579, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112541418329694208/vid/avc1/1280x720/h2UbO95knYIA0eb5.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112541418329694208/vid/avc1/3840x2160/9hltcERl8kPoLsvv.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112541418329694208/img/bWwbSs3TLx89nFj9.jpg", "dur": 60}], "quote": {"id": "2112529275022610869", "url": "https://x.com/citrini/status/2112529275022610869", "text": "What is AI really capable of in bio?\n\nTo separate hype from reality, we spent 3 months working firsthand with @AnthropicAI's  internal research model to see if it could create an experimental scorpion antivenom. \n\nIntroducing Citrini Therapeutics.\n\nhttps://www.citriniresearch.com/p/citrini-therapeutics", "name": "Citrini", "handle": "citrini", "avatar": "https://pbs.twimg.com/profile_images/2112500322148986880/exHhcKKE_200x200.jpg", "likes": 2763, "rts": 181, "replies": 139, "views": 986605, "ts": 1792501202, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.83, "thread": [], "tier": "must"}, {"id": "2112573329542394171", "url": "https://x.com/WatcherGuru/status/2112573329542394171", "text": "JUST IN: 🇫🇷 France's parliament advances legislation to impose 31.4% capital gains tax on crypto-to-stablecoin transactions.", "name": "Watcher.Guru", "handle": "WatcherGuru", "avatar": "https://pbs.twimg.com/profile_images/1641221212578754562/DfiC0KW2_200x200.png", "likes": 2605, "rts": 266, "replies": 494, "views": 774265, "ts": 1792511706, "media": [], "quote": null, "reply_to": null, "cat": "Money & Startups", "score": 5.83, "thread": [], "tier": "must"}, {"id": "2112581903555375210", "url": "https://x.com/TheSpacerr/status/2112581903555375210", "text": "🔥 Introducing Koi 👻 🔥\nA privacy-focused little ghost that lives on your Mac.\n\n→ An AI that sees your screen, like HeyClicky\n→ Dictation that types anywhere, like Wispr Flow\n→ Call notes, like Granola\n→ Documents, like Notion\n→ Flashcards, like Anki\n→ One calendar for every account, like Fantastical\n\nOne app instead of seven.\nYour documents, calls and calendar stay on your Mac.\n\nhttp://koiscribe.com\nMore below 👇", "name": "Irakli 🚀", "handle": "TheSpacerr", "avatar": "https://pbs.twimg.com/profile_images/2080386151093768192/h252LYvp_200x200.jpg", "likes": 96, "rts": 14, "replies": 61, "views": 5446, "ts": 1792513750, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112578988153466880/vid/avc1/1280x720/GHStfp1LZcOeaKFV.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112578988153466880/vid/avc1/1920x1080/vxf9KhA0yeaIg-pm.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112578988153466880/img/AuUCs_CqMyfi9an0.jpg", "dur": 32}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.82, "thread": [], "tier": "must"}, {"id": "2112484529029919106", "url": "https://x.com/rewind02/status/2112484529029919106", "text": "here’s how to build a japanese canal boat game with claude opus 5.5 + unity 6 + blender..\n\nthe trick is one system per prompt,  smart way to set it up:\n\n- step 1: create a unity 6 urp project and connect opus 5.5 through unity’s plugin and blender mcp\n- step 2: greybox the canal: water channel, stone walls, 2 bridges, docks\n- step 3: boat physics: throttle, steering, wake trails, speed in knots on the hud\n- step 4: opus models the props in blender: the covered boat, houses, the vermilion bridge, the pagoda, lanterns\n- step 5: water shader + day/night cycle + rain, with lanterns that switch on at dusk\n- step 6: a compass on top and 9 landmarks that unlock on the map (“water gate, 3 of 9”)\n- step 7: docking lessons: “come alongside the temple steps below 2 kn and press e”\n- step 8: opus playtests in play mode, reads the console and lists bugs before fixing\n\nwho does what:\n\n> blender: every model\n> unity 6: the water, the light, the weather, the ui\n> opus 5.5: boat physics, quests, scene setup, tests\n> you: steer it and say what feels off\n\ni like to test every feature at night in the rain. if it still looks good there, it’ll look good everywhere.", "name": "rewind", "handle": "rewind02", "avatar": "https://pbs.twimg.com/profile_images/2036190950545084416/aHeLH6m__200x200.jpg", "likes": 273, "rts": 16, "replies": 19, "views": 11598, "ts": 1792490534, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112484353343119360/vid/avc1/1138x720/2g_xJr9CiJjvsVNU.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112484353343119360/vid/avc1/1708x1080/vYcgzhcFLUAmkVDf.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112484353343119360/img/8Cy99_9W9GIOlNc3.jpg", "dur": 71}], "quote": {"id": "2110309991919853638", "url": "https://x.com/rewind02/status/2110309991919853638", "text": "https://x.com/i/article/2109565585021390848", "name": "rewind", "handle": "rewind02", "avatar": "https://pbs.twimg.com/profile_images/2036190950545084416/aHeLH6m__200x200.jpg", "likes": 370, "rts": 40, "replies": 25, "views": 220953, "ts": 1791972084, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.82, "thread": [], "tier": "must"}, {"id": "2112559935426887713", "url": "https://x.com/Texas_Twins_Dad/status/2112559935426887713", "text": "Grok Bot v0.71.2 is out. Here's what actually matters. Big difference in daily use!\n\n- Email tags: give your bot an address like you+receipts@, and set routines that only run for those emails.\n- Easier logins: one secure box for all fields. And if a routine needs a login, it asks you in chat instead of quietly stopping.\n- Stop means stop: it now ends background work too.\n- Smarter computer care: low on disk? It shows big files and only deletes with your OK.\n- Reconnects fast when your Mac sleeps or Wi-Fi changes.\n- Plugin skills limit: 24 → 200.\n- Bigger attachments: files up to 250MB, videos up to 1GB, 20 per message.\n\nI'm already on v0.72.0, checking out what's coming next. Stay tuned!", "name": "Texas Twins Dad", "handle": "Texas_Twins_Dad", "avatar": "https://pbs.twimg.com/profile_images/2001129830213967874/zFqUgDus_200x200.jpg", "likes": 212, "rts": 13, "replies": 13, "views": 14824, "ts": 1792508512, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112559778832449536/vid/avc1/720x720/5B2FTmrj1ceKCnNJ.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112559778832449536/vid/avc1/1080x1080/4VjS4vT1ZkoMdbBz.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112559778832449536/img/UEO8UowQat4dbi9o.jpg", "dur": 20}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.82, "thread": [], "tier": "must"}, {"id": "2112589000657514664", "url": "https://x.com/Greshamtrade/status/2112589000657514664", "text": "ex-SpaceXAI engineer shared his best tricks for getting more out of Grok Bot, and this is a f*cking goldmine\n\nhis Grok Bot setup went from 100,000 to 12,500 tokens per task. 8x less usage, fewer failed runs, and 10x more usable results from the same budget\n\n20 GitHub repos he used to cut costs and improve his Grok Bot’s results:\n\n01 JSON Repair → fix malformed JSON in code before asking the model to generate the entire response again\nhttp://github.com/mangiucugna/json_repair\n\n02 Docling → turn PDFs and office documents into structured content, preserving layout and tables so your bot gets cleaner material to work with\nhttp://github.com/docling-project/docling\n\n03 PyMuPDF4LLM → extract PDFs into Markdown, then select the pages and sections your task needs instead of loading the whole document\nhttp://github.com/pymupdf/pymupdf4llm\n\n04 LanceDB → store searchable document chunks and retrieve relevant evidence for each request instead of attaching the entire archive\nhttp://github.com/lancedb/lancedb\n\n05 FastEmbed → generate embeddings locally with supported models, reducing reliance on paid embedding calls when indexing and searching your material\nhttp://github.com/qdrant/fastembed\n\n06 FlashRank → rerank search results before generation so your bot reads the strongest passages rather than every vaguely related match\nhttp://github.com/PrithivirajDamodaran/FlashRank\n\n07 datasketch → detect near-duplicate text with similarity search, helping your pipeline remove repeated material before analysis\nhttp://github.com/ekzhu/datasketch\n\n08 joblib → cache expensive Python function results on disk and reuse them when the inputs match, avoiding repeated preprocessing\nhttp://github.com/joblib/joblib\n\n09 RQ → send background jobs to Python workers so code handles the queue while model calls happen only inside tasks that need them\nhttp://github.com/rq/rq\n\n10 Instructor → extract answers into typed fields and validate them automatically. set a retry limit so a failed extraction stays bounded\nhttp://github.com/567-labs/instructor\n\n11 Outlines → constrain supported model outputs to a defined structure, reducing formatting failures that trigger another generation\nhttp://github.com/dottxt-ai/outlines\n\n12 Guardrails → apply explicit input and output checks, catching configured failures before a response moves into the next workflow step\nhttp://github.com/guardrails-ai/guardrails\n\n13 DSPy → optimize prompts and examples against a defined quality metric, then test whether cheaper calls can meet your requirements\nhttp://github.com/stanfordnlp/dspy\n14 OptiLLM → test reasoning strategies on connected models and keep the approach that delivers better results within your task budget\nhttp://github.com/algorithmicsuperintelligence/optillm\n\n15 vLLM → serve compatible open models with batching and efficient memory management when you run your own API workers\nhttp://github.com/vllm-project/vllm\n\n16 SGLang → run compatible self-hosted workers with optimized serving and prefix reuse for requests sharing the same starting context\nhttp://github.com/sgl-project/sglang\n\n17 LMCache → reuse stored model attention state on compatible inference servers, reducing repeated processing of shared context\nhttp://github.com/LMCache/LMCache\n\n18 DeepEval → test cheaper calls and revised prompts against repeatable checks before trusting them with the full workload\nhttp://github.com/confident-ai/deepeval\n\n19 Ragas → evaluate retrieval and generated answers so shorter context doesn’t quietly turn into missing evidence or worse responses\nhttp://github.com/vibrantlabsai/ragas\n\n20 Laminar → trace instrumented agent runs and inspect the calls behind slow, expensive, or failed tasks before deciding what to change\nhttp://github.com/lmnr-ai/lmnr\n\nconnect the tools through your workflow code, terminal, or supported MCP integration. use serving tools for your own compatible workers and API tools for calls you control\n\nstart with one recurring task. remove duplicate inputs, retrieve better evidence, and compare accepted results against the full cost of the run\n\nclean inputs → reusable work → checked outputs → fewer expensive repeats\n\nsave this before your next upgrade\n\nthe full course below shows 7 fixes to get more finished work out of the same Grok Bot plan ↓", "name": "Gresham", "handle": "Greshamtrade", "avatar": "https://pbs.twimg.com/profile_images/2081690044461457408/I9NHHTUW_200x200.jpg", "likes": 157, "rts": 21, "replies": 16, "views": 15051, "ts": 1792515442, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112588856285392896/vid/avc1/720x900/_DQ4SKJxcdQbA_16.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112588856285392896/vid/avc1/1080x1350/52ps5MQ1BjuADTBC.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112588856285392896/img/eCP-W66niZCe-ONF.jpg", "dur": 19}], "quote": {"id": "2112214741103825314", "url": "https://x.com/Greshamtrade/status/2112214741103825314", "text": "https://x.com/i/article/2112211009951670272", "name": "Gresham", "handle": "Greshamtrade", "avatar": "https://pbs.twimg.com/profile_images/2081690044461457408/I9NHHTUW_200x200.jpg", "likes": 108, "rts": 10, "replies": 17, "views": 88630, "ts": 1792426211, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.82, "thread": [], "tier": "must"}, {"id": "2112539271223726552", "url": "https://x.com/DeemosTech/status/2112539271223726552", "text": "🔥Real-time path tracing for million-polygon PBR 3D Asset generated by AI—in your browser.\n\n🤖Built by @pissang1, this WebGPU renderer combines progressive path tracing, OpenPBR materials, and denoising. \n\n🔍We integrated it into https://Hyper3D.AI to reveal every detail.", "name": "Hyper3D by Deemos", "handle": "DeemosTech", "avatar": "https://pbs.twimg.com/profile_images/1932867461642366976/Yze9x58F_200x200.jpg", "likes": 221, "rts": 20, "replies": 5, "views": 13542, "ts": 1792503585, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112537052663394304/vid/avc1/1106x720/sn4kFut_GduZY3Sw.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112537052663394304/vid/avc1/1440x936/38hG03hsz4TyPwgg.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112537052663394304/img/AAKFohVOSASlUjTW.jpg", "dur": 28}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.81, "thread": [], "tier": "must"}, {"id": "2112521680853794840", "url": "https://x.com/CryptoQuill/status/2112521680853794840", "text": "When violence becomes a spectator sport that even children join, the neighborhood has traded collective safety for moral decay.\nWhen people film the fallen rather helping him get up, society is decayed. One shouldn't live in such neighborhood ", "name": "Cheeseburger 🧢", "handle": "CryptoQuill", "avatar": "https://pbs.twimg.com/profile_images/1417523926960263169/4a_ppDYb_200x200.jpg", "likes": 210, "rts": 11, "replies": 32, "views": 2504368, "ts": 1792499392, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112188685923823616/vid/avc1/640x360/5CUPmX3K6RZ_idgb.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112188685923823616/vid/avc1/1080x606/xxuYvzp1XKgCa_Hu.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112188685923823616/img/UkHjd1s41wFrfazq.jpg", "dur": 69}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.81, "thread": [], "tier": "must"}, {"id": "2112686985194451434", "url": "https://x.com/jon_barron/status/2112686985194451434", "text": "quickly! digest Brandon's paper now before he and argon solve navier stokes sometime late next week", "name": "Jon Barron", "handle": "jon_barron", "avatar": "https://pbs.twimg.com/profile_images/2027105545086537728/yiV10DcI_200x200.jpg", "likes": 158, "rts": 5, "replies": 2, "views": 13761, "ts": 1792538803, "media": [], "quote": {"id": "2112679237526426064", "url": "https://x.com/joiedeposter/status/2112679237526426064", "text": "Introducing beignet, a new neural field architecture!\n\nbeignet uses a multiresolution fourier frequency pyramid to achieve faster convergence and higher precision when solving PDEs and finding singularities.\n\nTeaser: here is beignet at work fitting an image (super fast)!", "name": "Brandon Zhao", "handle": "joiedeposter", "avatar": "https://pbs.twimg.com/profile_images/2107553088932605952/HMWTmaDA_200x200.jpg", "likes": 488, "rts": 46, "replies": 10, "views": 30881, "ts": 1792536956, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112672710140792832/vid/avc1/1200x720/Wq-eJApBL9YOlRac.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112672710140792832/vid/avc1/1696x1016/zhha4ufu7Bx3SVmz.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112672710140792832/img/MwDQw8om_4ZinfSu.jpg", "dur": 5}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.8, "thread": [], "tier": "must"}, {"id": "2112625656055972206", "url": "https://x.com/theallinpod/status/2112625656055972206", "text": "Figma CEO speaks out on Claude Design: “It's easy to mistake model progress for product progress.”\n\nFriedberg:\n\n“How worried were you when they came out with Claude Design, relative to what you guys were offering? Because the market looked at it and said, ‘Oh my God, Figma's dead. Claude is going to crush Figma.’\n\nDylan Field:\n\n“The nature of online discourse right now is, ‘We're so back, it's so over.’ And it's just a cycle, right?\n\nI think it's easy to mistake model progress for product progress.\n\nThe reality is a tool like Figma has taken a very long time to build and a very long time to make sure that we get the workflows right for our users, and we still have work to do.\n\nThey've made Claude Design into a product that is broad. So it's trying to do a lot of things. Like, you'll see posters and stuff as well, like graphic design scenarios, I believe, when you go to their homepage.\n\nAnd maybe they'll do well in some areas and not other areas. I'm not bullish or bearish on the product. I think it's just hard to make good design tools for professionals.”\n\n$FIG \n\n------------------------------\n\nThanks to our partners for making this possible!\n\nAs wealth grows, complexity compounds. Between investments, tax strategy and estate planning, coordinating it all can feel like a full-time job. Creative Planning can help with the heavy lifting.\nhttps://ad.doubleclick.net/ddm/trackclk/N2598215.3565131ALLIN/B36182939.452362736;dc_trk_aid=646454825;dc_trk_cid=260464105;dc_lat=;dc_rdid=;tag_for_child_directed_treatment=;tfua=;ltd=;dc_tdv=1\n\nWith over nine million acres protected across all fifty states, The Conservation Fund secures the irreplaceable lands we love. Learn more at http://conservationfund.org", "name": "The All-In Podcast", "handle": "theallinpod", "avatar": "https://pbs.twimg.com/profile_images/1789812359084519424/hg3j0g2E_200x200.jpg", "likes": 149, "rts": 9, "replies": 19, "views": 50398, "ts": 1792524181, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112625269429153792/vid/avc1/720x1280/Y4-nFr5ICWTSH1tN.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112625269429153792/vid/avc1/1080x1920/g2qRSXZ7NPDcFpfw.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112625269429153792/img/nX4nz7rdOvnYUla2.jpg", "dur": 51}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.8, "thread": [], "tier": "must"}, {"id": "2112568767435956428", "url": "https://x.com/JaynitMakwana/status/2112568767435956428", "text": "every humanoid robot so far looks like it's auditioning for a horror movie.\n\nVoxel from Tuesday Labs is the first one I'd actually let into my house. he's small, a bit obsessive about tidying, and will fluff your pillows 4 times a day if nobody stops him.\n\nthey're only making 999 in the first batch, and it's $200 to reserve one.", "name": "Jaynit Makwana", "handle": "JaynitMakwana", "avatar": "https://pbs.twimg.com/profile_images/1764990845030113280/gVhpRBbQ_200x200.jpg", "likes": 164, "rts": 27, "replies": 5, "views": 34114, "ts": 1792510618, "media": [{"type": "gif", "url": "https://video.twimg.com/tweet_video/HVFaEbNaYAA0gCZ.mp4", "hd": "https://video.twimg.com/tweet_video/HVFaEbNaYAA0gCZ.mp4", "thumb": "https://pbs.twimg.com/tweet_video_thumb/HVFaEbNaYAA0gCZ.jpg", "dur": 0}], "quote": {"id": "2112565146354860151", "url": "https://x.com/make_robot_go/status/2112565146354860151", "text": "Introducing Voxel, a droid butler made by Tuesday Labs.", "name": "Ros Shinkle", "handle": "make_robot_go", "avatar": "https://pbs.twimg.com/profile_images/1761551110303825920/JvPQiGQd_200x200.jpg", "likes": 2181, "rts": 228, "replies": 203, "views": 1850860, "ts": 1792509755, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112564839251931136/vid/avc1/960x720/cMYjra9bu_jYUTYR.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112564839251931136/vid/avc1/2880x2160/glhkyiQ6K97Rmq93.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112564839251931136/img/GKLfsqVaQmO0B-kn.jpg", "dur": 89}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.79, "thread": [], "tier": "must"}, {"id": "2112637131973878229", "url": "https://x.com/a16z/status/2112637131973878229", "text": "Karan Singhal of @OpenAI on the collapsing cost of intelligence, as seen on their health benchmark:\n\n\"GPT-6 Luna is our current cheapest frontier model on the API... It performed better than 5.6 Sol, which was literally our best model a month ago. And it performs better despite being 34x cheaper.\"\n\nMost tiers of model intelligence became more than 100x cheaper within roughly a year\n\nOne tier went from ~$32 to ~$0.02 per million tokens in two years", "name": "a16z", "handle": "a16z", "avatar": "https://pbs.twimg.com/profile_images/1919488160125616128/QAZXTMEj_200x200.png", "likes": 123, "rts": 19, "replies": 11, "views": 17719, "ts": 1792526917, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVGYRpcbcAA39kT.jpg?name=orig"}], "quote": {"id": "2112558129963815370", "url": "https://x.com/a16z/status/2112558129963815370", "text": "More than 300 million people use ChatGPT for health and wellness questions each week. OpenAI’s Karan Singhal thinks that’s only the beginning.\n\nKaran joins a16z's Jay Rughani to explain how OpenAI is building health intelligence, the advantages of using generalized models for health applications, how AI could lower the cost of healthcare, and more.\n\n00:00 Intro\n01:00 How OpenAI is building health intelligence\n07:57 A doctor in your pocket\n14:20 Creating trust with users\n19:44 Medical consensus and its 5–17 year lag\n28:03 AI for mental health\n30:59 How AI enables the healthcare ecosystem\n38:21 A \"move 37\" for health\n43:39 Driving down the cost of care\n50:27 Procedural care and what's next\n\nYouTube: https://youtu.be/9n0MI4D7TCM\n\n@thekaransinghal @JayRughani", "name": "a16z", "handle": "a16z", "avatar": "https://pbs.twimg.com/profile_images/1919488160125616128/QAZXTMEj_200x200.png", "likes": 135, "rts": 26, "replies": 7, "views": 75140, "ts": 1792508082, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112557641205780480/vid/avc1/640x360/NHdnNW8VbvWtleg7.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112557641205780480/vid/avc1/1280x720/GVYQC9jbYOIg50f8.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112557641205780480/img/-Z-bfGWX-m770-Sx.jpg", "dur": 3355}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.79, "thread": [], "tier": "must"}, {"id": "2112572096073372103", "url": "https://x.com/DocumentingAGI/status/2112572096073372103", "text": "Tuesday Labs launches Voxel, a bipedal home robot butler from former Boston Dynamics roboticist Ros Shinkle.\n\nIt targets everyday tasks like resetting the house, finding items, fetching, and tending, with engineered character (slightly obsessive tidying) so people actually want it living with them.\n\nLimited numbered Series-1 reservations now open. Real-world embodied agents that prioritize livability over warehouse demos are a meaningful step.", "name": "Documenting AGI", "handle": "DocumentingAGI", "avatar": "https://pbs.twimg.com/profile_images/2042920180825886721/2fa6dY9O_200x200.jpg", "likes": 198, "rts": 13, "replies": 8, "views": 21141, "ts": 1792511412, "media": [{"type": "gif", "url": "https://video.twimg.com/tweet_video/HVFc7xgWwAEJf-E.mp4", "hd": "https://video.twimg.com/tweet_video/HVFc7xgWwAEJf-E.mp4", "thumb": "https://pbs.twimg.com/tweet_video_thumb/HVFc7xgWwAEJf-E.jpg", "dur": 0}], "quote": {"id": "2112565146354860151", "url": "https://x.com/make_robot_go/status/2112565146354860151", "text": "Introducing Voxel, a droid butler made by Tuesday Labs.", "name": "Ros Shinkle", "handle": "make_robot_go", "avatar": "https://pbs.twimg.com/profile_images/1761551110303825920/JvPQiGQd_200x200.jpg", "likes": 2181, "rts": 228, "replies": 203, "views": 1849470, "ts": 1792509755, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112564839251931136/vid/avc1/960x720/cMYjra9bu_jYUTYR.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112564839251931136/vid/avc1/2880x2160/glhkyiQ6K97Rmq93.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112564839251931136/img/GKLfsqVaQmO0B-kn.jpg", "dur": 89}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.79, "thread": [], "tier": "must"}, {"id": "2112605265560481901", "url": "https://x.com/VALORANT/status/2112605265560481901", "text": "Pure dominance by Alpha", "name": "VALORANT", "handle": "VALORANT", "avatar": "https://pbs.twimg.com/profile_images/2102388787015757824/TXJb9TR2_200x200.jpg", "likes": 30615, "rts": 1785, "replies": 100, "views": 692507, "ts": 1792519320, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112590372694331392/vid/avc1/1280x720/U-3dgkduagHC8juk.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112590372694331392/vid/avc1/1920x1080/AYbNGLFPfQZOgh7i.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112590372694331392/img/ZvI64PegFTnowt6q.jpg", "dur": 8}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.79, "thread": [], "tier": "must"}, {"id": "2112588975923736788", "url": "https://x.com/ChelseaFC/status/2112588975923736788", "text": "Tuesday training. 🫡", "name": "Chelsea FC", "handle": "ChelseaFC", "avatar": "https://pbs.twimg.com/profile_images/2111907935496306688/XRdbWk-M_200x200.jpg", "likes": 29752, "rts": 2564, "replies": 188, "views": 498074, "ts": 1792515436, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112588889177157632/vid/avc1/720x900/KuMMsBy6OkVCnwZG.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112588889177157632/vid/avc1/2160x2700/WFUsbgTmn7tz-9nR.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112588889177157632/img/RnsmDmFmAbZrLpsX.jpg", "dur": 23}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.79, "thread": [], "tier": "must"}]);